/* Sai so khop cua ngan hang dang ap so voi duong cong bu muc tieu (luoi log
   49 diem 20 Hz-12,5 kHz) - hien thi truc tiep tren UI, khong giau sau PASS. */
var LOUD_FIT_FREQS = [];
for (var _lffI = 0; _lffI < 49; _lffI++) LOUD_FIT_FREQS.push(20*Math.pow(12500/20, _lffI/48));
var LOUD_FIT_FI = [], LOUD_FIT_FT = [];
for (var _lffJ = 0; _lffJ < LOUD_FIT_FREQS.length; _lffJ++){
  var _lffF = LOUD_FIT_FREQS[_lffJ];
  if (!isFinite(_lffF)) _lffF = 1000;
  var _lffFc = Math.max(ISO_FREQS[0], Math.min(ISO_FREQS[ISO_FREQS.length-1], _lffF));
  var _lffFi = 0; while (_lffFi < ISO_FREQS.length-2 && ISO_FREQS[_lffFi+1] < _lffFc) _lffFi++;
  LOUD_FIT_FI[_lffJ] = _lffFi;
  LOUD_FIT_FT[_lffJ] = (Math.log(_lffFc)-ISO_LOG_FREQS[_lffFi])/ISO_LOG_SPAN[_lffFi];
}
