  var lp500 = lowpassCoeffs(500, 1, fs), hp5000 = highpassCoeffs(5000, 1, fs), bp100 = bandpassCoeffs(100, 1.41, fs);
  var lpLo = biquadMagDb(lp500, 100, fs), lpHi = biquadMagDb(lp500, 8000, fs);
