  $("psV5").textContent = "LP500: 100 Hz " + fmtDb(lpLo) + " dB · 8 kHz " + fmtDb(lpHi) + " dB; HP5000: 100 Hz " + fmtDb(hpLo) + " dB · 8 kHz " + fmtDb(hpHi) + " dB; BP100: 100 Hz " + fmtDb(bpAt) + " dB · 1 kHz " + fmtDb(bpFar) + " dB; offset RMS sine " + fmtDb(oRms) + " dB";
