function hrtfWrapAz(a){
  var v = typeof a === "number" ? a + 0 : parseFloat(a); if (!isFinite(v)) return 0;
  if (v > 7200 || v < -7200){
    var _r = v % 360;
    if (_r > 180) _r -= 360; else if (_r <= -180) _r += 360;
    return _r;
  }
  while (v > 180) v -= 360; while (v <= -180) v += 360; return v;
}
